insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_60_v1'
from (values
('127.399.d.1.A',3,'The letters CAD in drafting stand for:','["computer-aided design", "central area drawing", "copy and delete", "color and depth"]'::jsonb,0,'CAD means computer-aided design (or drafting).','original'),
('127.399.d.1.A',4,'Compared with hand drafting, a major advantage of CADD is that drawings can be:','["only drawn once", "edited, copied, and reused quickly", "never changed", "printed only in one size"]'::jsonb,1,'Digital drawings are easy to modify and reuse.','original'),
('127.399.d.1.B',3,'Before exiting CADD software, a drafter should first:','["unplug the computer", "delete the file", "save the drawing", "pull the power cord"]'::jsonb,2,'Saving prevents lost or corrupted work.','original'),
('127.399.d.1.B',4,'Turning off the computer while a drawing file is open can cause the file to become:','["clearer", "encrypted by default", "smaller always", "corrupted"]'::jsonb,3,'Improper shutdown can damage files.','original'),
('127.399.d.1.C',3,'A native AutoCAD drawing file commonly uses the extension:','["DWG", "JPG", "MP3", "DOCX"]'::jsonb,0,'DWG is the native drawing format.','original'),
('127.399.d.1.C',4,'A drawing exchange format that many CAD programs can open is:','["WAV", "DXF", "PPT", "ZIP only"]'::jsonb,1,'DXF is a widely supported exchange format.','original'),
('127.399.d.1.D',3,'To avoid losing work during a long drawing session, a drafter should:','["never save", "save once at the end", "save often", "close without saving"]'::jsonb,2,'Frequent saves protect progress.','original'),
('127.399.d.1.D',4,'Saving a drawing under a new name while keeping the original untouched uses the:','["Close without saving", "Undo only", "Erase command", "Save As command"]'::jsonb,3,'Save As creates a new file.','original'),
('127.399.d.1.E',3,'Before drawing a floor plan in feet and inches, a drafter sets the drawing:','["units", "password", "font only", "wallpaper"]'::jsonb,0,'Units define how measurements are entered and shown.','original'),
('127.399.d.1.E',4,'Drawing limits define the:','["file name", "working area of the drawing", "screen color", "printer brand"]'::jsonb,1,'Limits mark the drawing boundary.','original'),
('127.399.d.1.F',3,'In the Cartesian coordinate system, the point where the X and Y axes cross is called the:','["limit", "snap", "origin", "vertex only"]'::jsonb,2,'The origin is 0,0.','original'),
('127.399.d.1.F',4,'A point entered as 3,4 is located:','["at the origin", "4 units along X and 3 along Y", "3 units from the screen edge", "3 units along X and 4 units along Y from the origin"]'::jsonb,3,'Coordinates are given as X,Y.','original'),
('127.399.d.1.G',3,'The snap function forces the cursor to move in:','["fixed increments", "the opposite direction", "a spiral", "random jumps"]'::jsonb,0,'Snap restricts the cursor to set spacing.','original'),
('127.399.d.1.G',4,'The grid in CADD software is best described as:','["a layer name", "a pattern of dots that helps you judge distance", "a plotting setting only", "a drawn object"]'::jsonb,1,'Grid dots are visual references and are not plotted.','original'),
('127.399.d.1.H',3,'The command line in CADD software is used to:','["hide the drawing", "print layers only", "type commands and respond to prompts", "store paper"]'::jsonb,2,'The command line shows and accepts commands.','original'),
('127.399.d.1.H',4,'Dynamic input displays command prompts and values:','["on a printout", "only on the status bar", "in the title block", "near the cursor"]'::jsonb,3,'Dynamic input places tooltips at the cursor.','original'),
('127.399.d.2.A',3,'Which tool is used to draw a straight segment between two points?','["line tool", "circle tool", "spline tool", "hatch tool"]'::jsonb,0,'The line tool draws segments.','original'),
('127.399.d.2.A',4,'Entering a length and a direction angle to draw a line uses:','["a color table", "polar coordinates", "no coordinates", "a printer driver"]'::jsonb,1,'Polar input uses distance and angle.','original'),
('127.399.d.2.B',3,'To draw a circle, a drafter can specify the center point and the:','["paper size", "layer color only", "radius or diameter", "file name"]'::jsonb,2,'Circles need a center and size.','original'),
('127.399.d.2.B',4,'An ellipse differs from a circle because an ellipse has:','["a single radius", "straight sides", "no center", "a major axis and a minor axis of different lengths"]'::jsonb,3,'Ellipses have two axes.','original'),
('127.399.d.2.C',3,'A polyline is a connected sequence of segments that acts as:','["a single object", "a layer", "a text block", "unrelated lines"]'::jsonb,0,'A polyline is one object.','original'),
('127.399.d.2.C',4,'A donut with an inside diameter of zero is drawn as a:','["square", "filled circle", "line", "spline"]'::jsonb,1,'Zero inside diameter fills the ring.','original'),
('127.399.d.2.D',3,'A true spline curve is a smooth curve that passes through or near a set of:','["blocks", "text styles", "control or fit points", "layer names"]'::jsonb,2,'Splines are defined by points.','original'),
('127.399.d.2.D',4,'Splines are useful for drawing:','["title blocks", "straight walls only", "text", "free-form curves such as a contour line"]'::jsonb,3,'Splines model irregular curves.','original'),
('127.399.d.2.E',3,'A drawing template saves time because it stores settings such as units, layers, and the:','["title block", "password", "operating system", "printer"]'::jsonb,0,'Templates preload standard settings.','original'),
('127.399.d.2.E',4,'Drawing templates are usually saved with the extension:','["DWG", "DWT", "DXF", "BAK"]'::jsonb,1,'DWT is the template extension.','original'),
('127.399.d.2.F',3,'On a technical drawing, visible edges are shown with thick:','["center lines", "dashed lines", "continuous lines", "dotted lines"]'::jsonb,2,'Object lines are thick and continuous.','original'),
('127.399.d.2.F',4,'Hidden features behind a surface are shown with:','["thick solid lines", "dimension lines", "cutting-plane lines only", "dashed lines"]'::jsonb,3,'Hidden lines are dashed.','original'),
('127.399.d.2.G',3,'Layers in CADD are like transparent sheets used to organize:','["drawing objects", "staff members", "printers", "file extensions"]'::jsonb,0,'Layers group related objects.','original'),
('127.399.d.2.G',4,'Turning a layer off causes the objects on it to:','["be deleted", "become invisible", "move to another file", "change color permanently"]'::jsonb,1,'Off layers are hidden, not erased.','original'),
('127.399.d.2.H',3,'To keep dimensions separate from walls in a floor plan, put them on:','["no layer", "the same layer always", "a different layer", "a printer"]'::jsonb,2,'Separate layers aid control.','original'),
('127.399.d.2.H',4,'The layer that is currently active is the one on which:','["text is erased", "old objects are deleted", "plots are saved", "new objects are drawn"]'::jsonb,3,'New objects go on the current layer.','original'),
('127.399.d.2.I',3,'Before printing a drawing, a drafter should choose the printer and the:','["paper size and plot scale", "keyboard layout", "font name only", "file password"]'::jsonb,0,'Plot settings control output.','original'),
('127.399.d.2.I',4,'A plot preview is used to:','["change the units", "check how the sheet will look before printing", "close the program", "delete the drawing"]'::jsonb,1,'Preview avoids wasted prints.','original'),
('127.399.d.2.J',3,'Working in a planned order, such as drawing the outline before the details, shows good:','["guessing", "luck", "organizational skills", "speed only"]'::jsonb,2,'Sequencing the work improves efficiency.','original'),
('127.399.d.2.J',4,'Drawing the large basic shapes first and the small features last helps to:','["slow plotting", "hide layers", "increase errors", "reduce rework"]'::jsonb,3,'A planned sequence prevents redoing work.','original'),
('127.399.d.2.K',3,'A hexagon can be constructed in CADD with the:','["polygon tool", "text tool", "title tool", "hatch tool"]'::jsonb,0,'The polygon tool makes regular shapes.','original'),
('127.399.d.2.K',4,'A circle drawn tangent to two lines is constructed using the circle option called:','["center, diameter only", "tangent, tangent, radius", "three-point text", "spline fit"]'::jsonb,1,'TTR creates tangent circles.','original'),
('127.399.d.2.L',3,'Text on a drawing should have a style and a height that make it:','["hidden", "colored at random", "readable at the plotted scale", "tiny and faint"]'::jsonb,2,'Annotation must be legible.','original'),
('127.399.d.2.L',4,'Annotative or scaled text height at a scale of 1/4 inch per foot must be larger on screen so that it plots at:','["zero height", "any random height", "the screen height", "the required printed height"]'::jsonb,3,'Text height is scaled to plot correctly.','original'),
('127.399.d.2.M',3,'Object snap lets the cursor lock exactly onto a feature such as an:','["endpoint or midpoint", "printer", "empty space", "menu color"]'::jsonb,0,'Object snaps give precise positioning.','original'),
('127.399.d.2.M',4,'Ortho mode restricts cursor movement to:','["random angles", "horizontal and vertical directions", "diagonals only", "curved paths"]'::jsonb,1,'Ortho forces straight alignment.','original'),
('127.399.d.2.N',3,'The command used to remove an object from a drawing is:','["save", "regen", "erase", "plot"]'::jsonb,2,'Erase deletes objects.','original'),
('127.399.d.2.N',4,'The undo command is used to:','["print the drawing", "rename a layer", "exit the program", "reverse the last action"]'::jsonb,3,'Undo reverses commands.','original'),
('127.399.d.2.O',3,'Zooming in on a drawing changes the:','["displayed view only, not the object size", "plot scale", "drawing units", "actual size of objects"]'::jsonb,0,'Zoom changes the view.','original'),
('127.399.d.2.O',4,'Panning a drawing moves the view without changing:','["the mouse", "the zoom level", "the screen", "the date"]'::jsonb,1,'Pan shifts the view.','original'),
('127.399.d.2.P',3,'A layout (paper space) is used to arrange views for:','["editing objects only", "saving layers", "plotting on a sheet", "typing commands"]'::jsonb,2,'Layouts prepare sheets for plotting.','original'),
('127.399.d.2.P',4,'A drawing plotted at 1/4 inch = 1 foot means 1 inch on paper represents:','["40 feet", "12 inches", "1 foot", "4 feet"]'::jsonb,3,'1 / (1/4) = 4 feet per inch.','original'),
('127.399.d.2.Q',3,'The command that reports how far apart two picked points are is:','["distance", "extend", "trim", "array"]'::jsonb,0,'Query commands report data.','original'),
('127.399.d.2.Q',4,'The list command displays:','["a plot", "the properties of a selected object", "printer ink", "a file folder"]'::jsonb,1,'List shows object database information.','original'),
('127.399.d.2.R',3,'To shift an object to a new location without changing its size, use:','["extend", "stretch only", "move", "scale"]'::jsonb,2,'Move changes location.','original'),
('127.399.d.2.R',4,'The offset command creates:','["a mirror copy", "a deleted copy", "a rotated copy", "a parallel copy at a set distance"]'::jsonb,3,'Offset makes parallel objects.','original'),
('127.399.d.2.S',3,'The fillet command creates a rounded corner between two objects using a specified:','["radius", "layer", "plot scale", "font"]'::jsonb,0,'Fillet uses a radius.','original'),
('127.399.d.2.S',4,'A fillet radius of zero between two lines produces a:','["circle", "sharp corner", "spline", "gap"]'::jsonb,1,'Zero radius joins the lines at a corner.','original'),
('127.399.d.2.T',3,'Trim removes the part of an object that extends beyond a:','["layer", "dimension", "cutting edge", "text"]'::jsonb,2,'Trim cuts to boundaries.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_60_v1'
from (values
('127.399.d.2.T',4,'The extend command lengthens an object until it meets a:','["printer", "viewport", "title block", "boundary edge"]'::jsonb,3,'Extend runs to a boundary.','original'),
('127.399.d.2.U',3,'The break command removes a portion of an object, leaving:','["a gap", "a title", "a copy", "a circle"]'::jsonb,0,'Break splits or removes a segment.','original'),
('127.399.d.2.U',4,'The join command combines collinear lines into:','["a block", "one line", "one circle", "a dimension"]'::jsonb,1,'Join merges objects.','original'),
('127.399.d.2.V',3,'The Properties palette can be used to change an object''s color, layer, and:','["printer brand", "file name", "linetype", "keyboard"]'::jsonb,2,'Properties include linetype.','original'),
('127.399.d.2.V',4,'Changing an object''s layer using the Properties palette also changes its:','["position", "units", "size", "assigned layer color and linetype by default"]'::jsonb,3,'ByLayer properties follow the layer.','original'),
('127.399.d.2.W',3,'Hatching is used to fill an enclosed area with a:','["pattern", "voltage", "units", "file"]'::jsonb,0,'Hatch patterns show material or section.','original'),
('127.399.d.2.W',4,'To calculate the area of a hatched region, a drafter can read the area from the hatch:','["layer name", "properties or the query area command", "text style", "plot scale only"]'::jsonb,1,'CADD can report enclosed area.','original'),
('127.399.d.3.A',3,'Multiple viewports in the drawing window let a drafter see:','["the printer", "no views", "several views of the model at the same time", "only one view"]'::jsonb,2,'Viewports show different areas or angles together.','original'),
('127.399.d.3.A',4,'Working in one viewport while another shows a zoomed-out view helps a drafter to:','["hide the model", "avoid zooming", "lose the layers", "keep track of detail and the whole drawing"]'::jsonb,3,'Multiple viewports combine overview and detail.','original'),
('127.399.d.3.B',3,'To start a line at the middle of a circle, use the object snap called:','["center", "grid", "perpendicular", "quadrant text"]'::jsonb,0,'Center snaps to the circle center.','original'),
('127.399.d.3.B',4,'To draw a line that meets another line at exactly 90 degrees, choose the object snap:','["insert", "perpendicular", "endpoint", "nearest"]'::jsonb,1,'Perpendicular snaps at right angles.','original'),
('127.399.d.3.C',3,'An orthographic drawing shows an object using several views such as the front, top, and:','["inside only", "color only", "right side", "price"]'::jsonb,2,'Orthographic projection uses principal views.','original'),
('127.399.d.3.C',4,'In an orthographic drawing, the top view is normally placed:','["below the front view", "off the sheet", "beside the title", "above the front view"]'::jsonb,3,'Standard view arrangement.','original'),
('127.399.d.3.D',3,'The first step in analyzing a design problem is to:','["identify the constraints and requirements", "buy materials", "start plotting", "name the file"]'::jsonb,0,'Understand the problem first.','original'),
('127.399.d.3.D',4,'A design that does not fit inside the available space has failed which type of requirement?','["a color preference", "a size constraint", "a title block rule", "a font rule"]'::jsonb,1,'Size limits are constraints.','original'),
('127.399.d.3.E',3,'In a site layout, scale and environmental features such as slope affect the placement of:','["title blocks", "line weights only", "structures and drives", "font styles"]'::jsonb,2,'Site conditions affect design.','original'),
('127.399.d.3.E',4,'Drawing a building so its large windows face the sun to gain heat is an example of using:','["text styles", "random placement", "block libraries only", "environmental features in design"]'::jsonb,3,'Orientation uses the environment.','original'),
('127.399.d.3.F',3,'A multi-view scaled drawing shows the object in views that are all drawn at the:','["same scale unless noted", "no scale", "different random scales", "smallest scale"]'::jsonb,0,'Views share a scale unless labeled.','original'),
('127.399.d.3.F',4,'If a view differs from the sheet''s main scale, the drafter should:','["delete the view", "label that view with its own scale", "hide the scale", "use red lines"]'::jsonb,1,'Different scales must be noted.','original'),
('127.399.d.3.G',3,'The scale chosen for a drawing should allow the object to fit on the sheet and show:','["no detail", "only dimensions", "enough detail to be understood", "only the title"]'::jsonb,2,'Scale balances size and clarity.','original'),
('127.399.d.3.G',4,'A large building plan is commonly drawn at a scale such as:','["full size", "10 inches = 1 foot", "1 inch = 1 inch", "1/4 inch = 1 foot"]'::jsonb,3,'Architectural plans use reduced scales.','original'),
('127.399.d.3.H',3,'In an orthographic drawing, a horizontal flat surface appears as a line in the:','["front view", "scale bar", "top view only", "title block"]'::jsonb,0,'A horizontal surface is edge-on in the front view.','original'),
('127.399.d.3.H',4,'A vertical surface parallel to the front plane appears in its true shape in the:','["right side edge", "front view", "section only", "top view"]'::jsonb,1,'Surfaces parallel to a plane show true shape there.','original'),
('127.399.d.3.I',3,'A round hole in a surface that is parallel to the viewing plane appears as a:','["square", "line", "circle", "spline"]'::jsonb,2,'Parallel faces show true shape.','original'),
('127.399.d.3.I',4,'A circle on a surface that is perpendicular to the viewing plane appears as a:','["dot", "circle", "ellipse only", "line"]'::jsonb,3,'Edge-on circles look like lines.','original'),
('127.399.d.3.J',3,'A sectional view shows the inside of an object by imagining it:','["cut open by a cutting plane", "turned off", "painted", "painted blue"]'::jsonb,0,'Sections reveal internal features.','original'),
('127.399.d.3.J',4,'A conventional break is used on a drawing to shorten a view of a long part that has:','["no length", "a uniform cross section", "hidden holes only", "a changing cross section"]'::jsonb,1,'Breaks save space on uniform parts.','original'),
('127.399.d.3.K',3,'An assembly drawing shows how:','["layers are named", "the sheet is printed", "parts fit together", "a single part is made"]'::jsonb,2,'Assemblies show how parts relate.','original'),
('127.399.d.3.K',4,'Balloons with numbers on an assembly drawing refer to items in the:','["coordinate system", "layer list", "plot style", "parts list"]'::jsonb,3,'Balloons key to the parts list.','original'),
('127.399.d.3.L',3,'A detail drawing gives complete information about a:','["single part", "whole building", "print queue", "layer set"]'::jsonb,0,'Detail drawings describe one part.','original'),
('127.399.d.3.L',4,'A detail drawing must include the dimensions, material, and:','["the plotter model", "tolerances needed to make the part", "the user''s name only", "color of the drafter''s pen"]'::jsonb,1,'Details include data for manufacturing.','original'),
('127.399.d.3.M',3,'The title block of a technical drawing usually includes the drawing name, scale, date, and the:','["stock price", "weather", "drafter''s name or initials", "file size"]'::jsonb,2,'Title blocks identify the drawing.','original'),
('127.399.d.3.M',4,'Different types of technical drawings, such as mechanical or architectural, use title blocks that:','["are always blank", "are identical", "are never used", "follow the standard for that field"]'::jsonb,3,'Fields have their own title block formats.','original'),
('127.399.d.4.A',3,'Standard lettering on a technical drawing is typically:','["uppercase, single-stroke, and legible", "decorative script", "tiny italic", "handwriting only"]'::jsonb,0,'Engineering lettering is simple and clear.','original'),
('127.399.d.4.A',4,'A common standard height for text on a plotted drawing is:','["1/64 inch", "1/8 inch", "1 inch", "3 inches"]'::jsonb,1,'1/8 inch is typical.','original'),
('127.399.d.4.B',3,'A drawing is plotted at 1/4 inch = 1 foot, a scale factor of 48. Text that should plot 1/8 inch high must be drawn:','["48 inches high", "1/48 inch high", "6 inches high", "1/8 inch high"]'::jsonb,2,'1/8 x 48 = 6 inches.','original'),
('127.399.d.4.B',4,'At a scale factor of 2 (half size), text that should plot 1/8 inch high should be created at:','["2 inches", "1/8 inch", "1/16 inch", "1/4 inch"]'::jsonb,3,'1/8 x 2 = 1/4.','original'),
('127.399.d.4.C',3,'A text style defines the font, height, and:','["width factor and orientation", "layer order", "paper brand", "plotting date"]'::jsonb,0,'Styles store text properties.','original'),
('127.399.d.4.C',4,'Using a clear, simple font for notes on a drawing improves its:','["unit setting", "readability", "print speed only", "file size only"]'::jsonb,1,'Clarity helps readers.','original'),
('127.399.d.4.D',3,'Multi-line text is best used for:','["single short labels only", "dimension lines", "paragraphs and general notes", "hatches"]'::jsonb,2,'MTEXT supports wrapped paragraphs.','original'),
('127.399.d.4.D',4,'Single-line text is most appropriate for a:','["drawing template", "table", "long paragraph", "short label"]'::jsonb,3,'Single-line text suits brief labels.','original'),
('127.399.d.4.E',3,'To change the words in a note already on a drawing, you can:','["double-click the text to edit it", "erase the layer", "change the units", "re-plot the sheet"]'::jsonb,0,'Text can be edited in place.','original'),
('127.399.d.4.E',4,'Editing the text style of existing notes will update:','["no text", "all text that uses that style", "only new layers", "the title block only"]'::jsonb,1,'Styles control linked text.','original'),
('127.399.d.4.F',3,'A table in CADD is useful for creating:','["a spline", "a hatch pattern", "a parts list or schedule", "a viewport"]'::jsonb,2,'Tables organize data.','original'),
('127.399.d.4.F',4,'A door schedule on a floor plan is typically made with a:','["revision cloud", "circle", "dimension", "table"]'::jsonb,3,'Schedules are tables.','original'),
('127.399.d.5.A',3,'A chamfer on a corner replaces the sharp edge with a:','["angled cut", "rounded curve", "hole", "hatch"]'::jsonb,0,'Chamfer is a bevel.','original'),
('127.399.d.5.A',4,'Unlike a fillet, a chamfer connects two lines with a:','["curve", "straight segment", "dimension", "spline"]'::jsonb,1,'Chamfers are straight; fillets are curved.','original'),
('127.399.d.5.B',3,'Editing tools in CADD allow a drafter to change existing drawings:','["only by erasing everything", "only at plot time", "without redrawing from scratch", "by hand"]'::jsonb,2,'Modify tools save time.','original'),
('127.399.d.5.B',4,'The stretch command changes the shape of an object by moving selected:','["layers", "units", "colors", "vertices or endpoints"]'::jsonb,3,'Stretch moves selected points.','original'),
('127.399.d.5.C',3,'The polyline edit command can join separate lines into:','["one polyline", "one block", "one layer", "one viewport"]'::jsonb,0,'PEDIT joins connected segments.','original'),
('127.399.d.5.C',4,'Spline edit lets a drafter adjust a curve by moving its:','["file names", "fit or control points", "layers", "fonts"]'::jsonb,1,'Splines are reshaped by points.','original'),
('127.399.d.5.D',3,'The copy command makes a duplicate of an object and:','["deletes the original", "closes the file", "leaves the original in place", "changes the layer"]'::jsonb,2,'Copy duplicates.','original'),
('127.399.d.5.D',4,'Using a base point when moving an object lets the drafter control exactly:','["the plot scale", "the text height", "the layer color", "how far and where the object is displaced"]'::jsonb,3,'Base point and second point define displacement.','original'),
('127.399.d.5.E',3,'The mirror command creates a reflected copy of an object across:','["a mirror line", "a layer", "a title block", "a grid dot"]'::jsonb,0,'Mirror needs an axis.','original'),
('127.399.d.5.E',4,'Drawing half of a symmetrical part and then mirroring it helps to:','["slow plotting", "save drawing time and ensure symmetry", "increase errors", "remove a layer"]'::jsonb,1,'Mirroring ensures exact symmetry.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_60_v1'
from (values
('127.399.d.5.F',3,'If an object is scaled by a factor of 2, each of its lengths becomes:','["unchanged", "four times shorter", "twice as long", "half as long"]'::jsonb,2,'Scale factor multiplies lengths.','original'),
('127.399.d.5.F',4,'A rectangular array of 3 rows and 4 columns creates how many objects in all (including the original)?','["7", "1", "34", "12"]'::jsonb,3,'3 x 4 = 12.','original'),
('127.399.d.6.A',3,'Grips are small squares that appear on a selected object and allow quick:','["editing such as stretching or moving", "saving files", "changing units", "printing"]'::jsonb,0,'Grips give direct edit handles.','original'),
('127.399.d.6.A',4,'Selecting a grip and pressing the space bar cycles through edit modes such as stretch, move, rotate, scale, and:','["save", "mirror", "quit", "print"]'::jsonb,1,'Grip modes include mirror.','original'),
('127.399.d.6.B',3,'The Properties palette displays an object''s layer, color, and:','["author''s address", "phone number", "dimensions or geometry", "file path"]'::jsonb,2,'Properties show object data.','original'),
('127.399.d.6.B',4,'Quick Properties gives a short list of the most common:','["printer settings", "fonts only", "user names", "properties for the selected object"]'::jsonb,3,'Quick Properties is a compact version.','original'),
('127.399.d.6.C',3,'The Quick Select dialog box lets a drafter select objects by their:','["property such as layer or type", "name only", "price", "owner"]'::jsonb,0,'Filters choose matching objects.','original'),
('127.399.d.6.C',4,'Using Quick Select to choose all circles on a layer is faster than:','["using the command line", "clicking each circle one at a time", "saving the drawing", "opening a file"]'::jsonb,1,'Filtering reduces clicking.','original'),
('127.399.d.7.A',3,'A standard dimensioning rule is to place dimensions outside the object and avoid:','["using numbers", "using arrows", "repeating the same dimension", "using units"]'::jsonb,2,'Each feature is dimensioned once.','original'),
('127.399.d.7.A',4,'Dimension lines should not cross each other, and extension lines have a small gap from the:','["viewport", "title block", "sheet border", "object being dimensioned"]'::jsonb,3,'A visible gap separates extension lines from the part.','original'),
('127.399.d.7.B',3,'A drawing scale such as 1:2 means the drawing is:','["half the actual size", "twice the actual size", "full size", "not to scale"]'::jsonb,0,'1:2 is a reduction.','original'),
('127.399.d.7.B',4,'Dimension values on a scaled drawing must show the:','["size on screen", "true size of the object", "size on paper", "scale of the printer"]'::jsonb,1,'Dimensions report real measurements.','original'),
('127.399.d.7.C',3,'A dimension style controls the arrow size, text height, and the:','["file name", "printer driver", "format of dimensions", "user name"]'::jsonb,2,'Styles store dimension settings.','original'),
('127.399.d.7.C',4,'Changing a dimension style updates all dimensions that:','["are in other files only", "are on other drawings", "are erased", "use that style"]'::jsonb,3,'Styles are linked to dimensions.','original'),
('127.399.d.7.D',3,'A linear dimension measures the distance between two:','["points along a horizontal or vertical direction", "text styles", "layers", "colors"]'::jsonb,0,'Linear dimensions measure straight distance.','original'),
('127.399.d.7.D',4,'An angular dimension is used to measure the angle between:','["two layers", "two lines", "two text blocks", "two files"]'::jsonb,1,'Angular dimensions measure angles.','original'),
('127.399.d.7.E',3,'Chain dimensions are placed:','["all from one baseline", "on top of each other", "end to end in a line", "in a circle"]'::jsonb,2,'Chain dimensions run in sequence.','original'),
('127.399.d.7.E',4,'Datum (baseline) dimensions all measure from the same:','["layer", "color", "scale", "starting edge or point"]'::jsonb,3,'Baseline dimensioning avoids accumulated error.','original'),
('127.399.d.7.F',3,'On a drawing, the symbol placed before a circle''s diameter value is:','["a circle with a slash", "R", "the letter D lowercase", "SQ"]'::jsonb,0,'The diameter symbol precedes the value.','original'),
('127.399.d.7.F',4,'A dimension for an arc usually gives its:','["diameter with a slash", "radius with an R", "volume", "area"]'::jsonb,1,'Arcs are dimensioned by radius.','original'),
('127.399.d.7.G',3,'The appearance of dimension text, such as its height, can be changed through the:','["layer name", "print queue", "dimension style", "file name"]'::jsonb,2,'Styles control appearance.','original'),
('127.399.d.7.G',4,'A dimension that shows a rounded value, such as 2.5 instead of 2.500, is set through the:','["plot style", "block name", "layer color", "precision setting"]'::jsonb,3,'Precision controls decimal places.','original'),
('127.399.d.7.H',3,'Equal spacing between stacked dimension lines makes a drawing:','["neater and easier to read", "less accurate", "slower to open", "harder to print"]'::jsonb,0,'Consistent spacing is a drafting standard.','original'),
('127.399.d.7.H',4,'A command that sets even spacing between parallel dimension lines is:','["dimension style delete", "dimension space", "dimension erase", "plot preview"]'::jsonb,1,'The DIMSPACE command evens spacing.','original'),
('127.399.d.8.A',3,'A block is a group of objects that is saved and treated as:','["a layer", "many separate lines", "a single object", "a printer"]'::jsonb,2,'Blocks group objects.','original'),
('127.399.d.8.A',4,'Making a block of a door symbol lets a drafter:','["use it only once", "avoid layers", "prevent editing", "reuse it throughout the drawing"]'::jsonb,3,'Blocks speed repeated use.','original'),
('127.399.d.8.B',3,'To place a copy of a block in a drawing, use the:','["insert command", "purge command", "plot command", "erase command"]'::jsonb,0,'Insert places blocks.','original'),
('127.399.d.8.B',4,'When inserting a block, the insertion point is where the block''s:','["color changes", "base point attaches", "name prints", "layer is deleted"]'::jsonb,1,'The base point locates the block.','original'),
('127.399.d.8.C',3,'Editing a block definition updates:','["only the first copy", "none of the copies", "all insertions of that block", "only the layer"]'::jsonb,2,'Blocks update globally.','original'),
('127.399.d.8.C',4,'One benefit of using blocks for repeated symbols is that a single change can be:','["restricted to one use", "made only by hand", "impossible", "made once and applied everywhere"]'::jsonb,3,'Block redefinition is efficient.','original'),
('127.399.d.8.D',3,'A block saved as a separate drawing file for use in other drawings is created with the:','["wblock (write block) command", "zoom command", "hatch command", "trim command"]'::jsonb,0,'WBLOCK writes a block to a file.','original'),
('127.399.d.8.D',4,'An advantage of saving a block as its own file is that it can be:','["printed only", "used in many different drawings", "used in only one drawing", "hidden permanently"]'::jsonb,1,'External blocks are portable.','original'),
('127.399.d.8.E',3,'A symbol library is a collection of:','["passwords", "printer settings", "commonly used blocks", "plot styles only"]'::jsonb,2,'Libraries store reusable symbols.','original'),
('127.399.d.8.E',4,'A well-organized symbol library saves time because drafters can:','["draw every symbol again", "avoid using layers", "ignore standards", "find and insert standard symbols quickly"]'::jsonb,3,'Libraries speed up work.','original'),
('127.399.d.8.F',3,'The purge command removes unused items such as:','["unreferenced blocks and layers", "the current layer", "the title block", "all drawn lines"]'::jsonb,0,'Purge cleans the file.','original'),
('127.399.d.8.F',4,'Purging a drawing before sending it to a client helps to reduce its:','["accuracy", "file size", "dimensions", "scale"]'::jsonb,1,'Removing unused items shrinks the file.','original'),
('127.399.d.9.A',3,'A pattern development of a cylinder lays out the lateral surface as a:','["cone", "triangle", "rectangle", "sphere"]'::jsonb,2,'A cylinder unrolls into a rectangle.','original'),
('127.399.d.9.A',4,'The length of the rectangle in the development of a cylinder with a 2-inch diameter is about:','["12.56 inches", "3.14 inches", "2 inches", "6.28 inches"]'::jsonb,3,'Circumference = pi x d = 6.28.','original'),
('127.399.d.9.B',3,'A transition piece connects two openings of different:','["shapes or sizes", "printers", "colors only", "brand names"]'::jsonb,0,'For example, a square-to-round duct.','original'),
('127.399.d.9.B',4,'Developments of transition pieces are commonly found using a method of:','["mirroring", "triangulation", "extruding only", "hatching"]'::jsonb,1,'Surfaces are divided into triangles.','original'),
('127.399.d.9.C',3,'When two pipes intersect, the drawing must show the line of:','["title", "gradient", "intersection", "extension"]'::jsonb,2,'Intersection curves define the joint.','original'),
('127.399.d.9.C',4,'Drawings involving intersecting pieces are important in sheet metal work because they show how to:','["print the sheet", "rename files", "name the layers", "cut and join the parts"]'::jsonb,3,'Fabricators need cut patterns.','original'),
('127.399.d.10.A',3,'Looking at a design problem from the viewpoint of the user can help a designer to:','["find new solutions", "skip drawings", "stop designing", "avoid planning"]'::jsonb,0,'New perspectives reveal options.','original'),
('127.399.d.10.A',4,'Asking a client what they dislike about their present kitchen is a way to:','["avoid drawings", "gain a new perspective on the design problem", "end the project", "shorten the plot"]'::jsonb,1,'Client feedback reveals needs.','original'),
('127.399.d.10.B',3,'Creative problem solving in design often begins with:','["avoiding sketches", "picking the first idea only", "brainstorming many ideas", "printing the drawing"]'::jsonb,2,'Brainstorming expands options.','original'),
('127.399.d.10.B',4,'After brainstorming several layouts, the designer should evaluate them against the:','["day of the week", "file extension", "paper color", "client''s requirements and constraints"]'::jsonb,3,'Evaluation uses criteria.','original'),
('127.399.d.10.C',3,'A site plan shows a building in relation to the:','["property and its surroundings", "interior wall colors", "kitchen cabinets only", "wiring colors"]'::jsonb,0,'Site plans show the lot context.','original'),
('127.399.d.10.C',4,'A site plan often includes property lines, setbacks, driveways, and a:','["title of a song", "north arrow", "phone book", "recipe"]'::jsonb,1,'North orientation is shown.','original'),
('127.399.d.10.D',3,'A floor plan is an overhead view of a building as if it were cut horizontally about:','["below the foundation", "at ground level only", "four feet above the floor", "at the roof peak"]'::jsonb,2,'Floor plan cuts are taken at window height.','original'),
('127.399.d.10.D',4,'Walls, doors, windows, and room names are all shown on a:','["plot plan only", "detail of a nail", "wall section", "floor plan"]'::jsonb,3,'Floor plans show layout.','original'),
('127.399.d.10.E',3,'An elevation drawing shows a building as viewed from the:','["side, front, or back", "under the ground", "above only", "inside the walls only"]'::jsonb,0,'Elevations are vertical views.','original'),
('127.399.d.10.E',4,'Exterior elevations typically show the building''s materials and the:','["names of workers", "heights of floors and roofs", "price lists", "tax records"]'::jsonb,1,'Elevations show vertical dimensions.','original'),
('127.399.d.10.F',3,'A roof plan is an overhead view that shows the roof''s:','["interior doors", "plumbing", "shape, slope, and ridge lines", "wall colors"]'::jsonb,2,'Roof plans show roof geometry.','original'),
('127.399.d.10.F',4,'A roof pitch of 6:12 means the roof rises 6 inches for every:','["12 feet of width", "6 feet of run", "12 inches of height", "12 inches of horizontal run"]'::jsonb,3,'Pitch is rise per 12 inches of run.','original'),
('127.399.d.10.G',4,'Doors and windows on a floor plan are linked to the schedule by:','["marks or tags", "colors", "line weights", "fonts"]'::jsonb,0,'Tags reference schedule entries.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_60_v1'
from (values
('127.399.d.10.H',3,'A wall section is a vertical cut through a wall that shows its:','["floor plan layout", "layers of construction", "paint colors only", "landscape"]'::jsonb,1,'Wall sections show construction detail.','original'),
('127.399.d.10.H',4,'A wall section typically shows the footing, foundation, framing, and:','["carpet brand", "parking lot", "roof connection", "owner"]'::jsonb,2,'Sections run from footing to roof.','original'),
('127.399.d.10.I',3,'A plot plan is drawn to show the building''s location on the:','["interior walls", "furniture", "roof shingles", "lot with distances to the property lines"]'::jsonb,3,'Plot plans locate the structure.','original'),
('127.399.d.10.I',4,'Building codes require setbacks, which are minimum distances between a building and the:','["property lines", "trees only", "neighbors'' furniture", "road signs"]'::jsonb,0,'Setbacks are shown on plot plans.','original'),
('127.399.d.10.J',3,'An electrical plan uses symbols to show the locations of outlets, switches, and:','["carpets", "light fixtures", "staircases only", "sinks"]'::jsonb,1,'Electrical plans locate fixtures.','original'),
('127.399.d.10.J',4,'A reflected ceiling plan is drawn as if looking:','["down at the floor", "at the roof from outside", "up at the ceiling", "through the walls sideways"]'::jsonb,2,'The plan is mirrored to the ceiling.','original'),
('127.399.d.11.A',3,'In a mechanical assembly project, each part is first drawn as a:','["legend", "single pixel", "title page", "separate detail drawing"]'::jsonb,3,'Individual parts are drawn first.','original'),
('127.399.d.11.A',4,'Drawing parts at full size (1:1) in the model before reducing the scale on the layout helps ensure:','["accurate dimensions", "hidden layers", "slower plotting", "larger files only"]'::jsonb,0,'Full-scale modeling preserves accuracy.','original'),
('127.399.d.11.B',3,'A closed assembly drawing shows the parts:','["scattered apart", "fitted together in their working positions", "in alphabetical order", "erased"]'::jsonb,1,'Closed assemblies show the assembled product.','original'),
('127.399.d.11.B',4,'Parts in a closed assembly must have mating dimensions that:','["are unlabeled", "are all identical", "fit together correctly", "differ widely"]'::jsonb,2,'Mating features must fit.','original'),
('127.399.d.11.C',3,'An exploded assembly drawing shows the parts:','["hidden", "merged into one", "erased", "separated along assembly lines"]'::jsonb,3,'Exploded views show how parts fit.','original'),
('127.399.d.11.C',4,'A parts list on an assembly drawing includes each part''s item number, name, quantity, and:','["material", "owner''s age", "weather", "printer"]'::jsonb,0,'Parts lists identify each part.','original'),
('127.400.d.1.A',3,'Absolute coordinates such as 5,3 are measured from the:','["last point drawn", "origin of the coordinate system", "screen corner", "printer margin"]'::jsonb,1,'Absolute values reference 0,0.','original'),
('127.400.d.1.A',4,'A relative coordinate entry of @4,0 draws a segment that is:','["at an angle of 4 degrees", "4 units up from the origin", "4 units long to the right of the last point", "4 units from the origin"]'::jsonb,2,'The @ symbol measures from the last point.','original'),
('127.400.d.1.B',3,'In modern CADD software, commands are grouped into tabs and panels on the:','["keyboard", "plotter", "power supply", "ribbon"]'::jsonb,3,'The ribbon organizes commands.','original'),
('127.400.d.1.B',4,'A drop-down menu in CADD software is opened by selecting a menu name such as File or:','["Edit", "Voltage", "Wall", "Plotter name"]'::jsonb,0,'Menu bars list command groups.','original'),
('127.400.d.1.C',3,'Typing the word LINE on the command line is an example of a:','["icon click", "type-in command", "pulldown menu pick", "hot spot"]'::jsonb,1,'Commands can be keyed in.','original'),
('127.400.d.1.C',4,'Clicking a small picture of a circle on a toolbar is using a(n):','["type-in command", "pulldown menu", "icon", "script"]'::jsonb,2,'Icons are toolbar buttons.','original'),
('127.400.d.1.D',3,'Which of these is a standard draw command?','["mirror", "trim", "erase", "rectangle"]'::jsonb,3,'Rectangle creates a new object.','original'),
('127.400.d.1.D',4,'The command that draws a smooth curved segment of a circle is:','["arc", "hatch", "offset", "line"]'::jsonb,0,'Arc draws part of a circle.','original'),
('127.400.d.1.E',3,'Which of these is a modifying command?','["polygon", "rotate", "line", "circle"]'::jsonb,1,'Rotate edits existing objects.','original'),
('127.400.d.1.E',4,'The command that lengthens or shortens objects to meet others is:','["text", "spline", "trim or extend", "plot"]'::jsonb,2,'Trim and extend modify objects.','original'),
('127.400.d.1.F',3,'Choosing Zoom Extents displays:','["a blank screen", "only one layer", "only the title block", "all objects in the drawing"]'::jsonb,3,'Zoom Extents fits the whole drawing.','original'),
('127.400.d.1.F',4,'Rotating the view of a 3D model with the orbit tool changes the:','["viewing angle of the model", "layer names", "units", "actual geometry"]'::jsonb,0,'Orbit changes only the view.','original'),
('127.400.d.1.G',3,'To change the arrowhead style on all dimensions, a drafter should modify the:','["plot scale", "dimension style", "block name", "layer color"]'::jsonb,1,'Styles control arrowheads.','original'),
('127.400.d.1.G',4,'A new dimension style can be created by starting from an existing one and:','["changing the units of the file", "closing the drawing", "modifying its settings and saving under a new name", "erasing all dimensions"]'::jsonb,2,'Styles can be copied and revised.','original'),
('127.400.d.2.A',3,'A pictorial sketch shows an object in a way that looks like a:','["list of parts only", "single line", "table of numbers", "photograph of its three-dimensional form"]'::jsonb,3,'Pictorials show depth.','original'),
('127.400.d.2.A',4,'A graphic description of a part that includes dimensions, notes, and views is called a:','["technical drawing", "brochure", "recipe", "movie"]'::jsonb,0,'Technical drawings describe parts graphically.','original'),
('127.400.d.2.B',3,'Making rough freehand sketches early in a design helps a designer to:','["avoid thinking", "explore and communicate ideas quickly", "avoid planning", "delay the project"]'::jsonb,1,'Sketching speeds idea generation.','original'),
('127.400.d.2.B',4,'Grid paper is useful for sketching because it helps keep lines straight and:','["colors bright", "files light", "proportions consistent", "text small"]'::jsonb,2,'Grid helps proportion.','original'),
('127.400.d.2.C',3,'A projection method that shows an object with all three principal axes at equal angles is:','["orthographic projection with one view", "perspective projection", "section projection", "isometric projection"]'::jsonb,3,'Isometric uses equal axis angles.','original'),
('127.400.d.2.C',4,'In orthographic projection, projectors from the object to the view are:','["parallel to each other and perpendicular to the plane", "random", "converging to a point", "curved"]'::jsonb,0,'Orthographic projectors are parallel.','original'),
('127.400.d.2.D',3,'When converting a hand sketch into an electronic drawing, a drafter should first establish the:','["plotter", "scale and overall dimensions", "file name only", "color scheme only"]'::jsonb,1,'Scale and sizes come first.','original'),
('127.400.d.2.D',4,'A drafter should clean up a scanned sketch by redrawing it with:','["freehand marks", "smudges", "precise lines, correct layers, and dimensions", "colors only"]'::jsonb,2,'Final drawings follow standards.','original'),
('127.400.d.3.A',3,'Before operating CADD software on a shared lab computer, a student should be sure to follow the lab''s:','["lunch menu", "weather alerts", "holiday schedule", "file naming and saving rules"]'::jsonb,3,'Labs have saving procedures.','original'),
('127.400.d.3.A',4,'Keyboard shortcuts in CADD software can increase a drafter''s:','["speed and efficiency", "file size", "error rate", "screen size"]'::jsonb,0,'Shortcuts save time.','original'),
('127.400.d.3.B',3,'To draw a closed shape with equal sides and angles, use the:','["text command", "polygon command", "hatch command", "spline command"]'::jsonb,1,'Polygon draws regular shapes.','original'),
('127.400.d.3.B',4,'The command for drawing a series of connected line and arc segments as one object is:','["trim", "mirror", "polyline", "array"]'::jsonb,2,'Polylines can include arcs.','original'),
('127.400.d.3.C',3,'The mirror command creates a reversed copy and offers the choice to:','["change the layers", "save the file", "erase the text", "keep or delete the original"]'::jsonb,3,'Mirror asks about the source.','original'),
('127.400.d.3.C',4,'The rotate command needs a base point and a:','["rotation angle", "scale factor", "file name", "layer name"]'::jsonb,0,'Rotate requires an angle.','original'),
('127.400.d.3.D',3,'A two-dimensional object has length and width, while a three-dimensional object also has:','["texture only", "depth or height", "color only", "sound"]'::jsonb,1,'3D adds a third dimension.','original'),
('127.400.d.3.D',4,'A solid box in CADD is defined by its length, width, and:','["text style", "layer", "height", "plot style"]'::jsonb,2,'Boxes are 3D primitives.','original'),
('127.400.d.3.E',3,'The extrude command can convert a closed 2D shape into a:','["text block", "hatch", "dimension", "3D solid"]'::jsonb,3,'Extrusion adds height.','original'),
('127.400.d.3.E',4,'Extruding a 2-inch square profile by 5 inches creates a solid whose volume is:','["20 cubic inches", "7 cubic inches", "25 cubic inches", "10 cubic inches"]'::jsonb,0,'2 x 2 x 5 = 20.','original'),
('127.400.d.3.F',3,'A 2D view such as a front elevation can be generated from a 3D model by:','["changing units", "creating a view or flattened projection", "erasing the model", "adding text"]'::jsonb,1,'CADD can generate 2D views.','original'),
