('127.400.d.3.H',4,'Architects use xrefs to place a base floor plan under other drawings such as:','["emails", "music files", "electrical or plumbing plans", "spreadsheets"]'::jsonb,2,'Shared base plans coordinate trades.','original'),
('127.400.d.3.I',3,'CADD programs can import files of other formats, such as:','["movie scripts", "e-books", "music tracks", "DXF or PDF underlays"]'::jsonb,3,'Common exchange formats.','original'),
